66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
72	
73	    /**
74	     * The HTTP request header a client may send to make a create idempotent. When a create repeats
75	     * with a key already seen, the originally created owner is returned instead of a duplicate.
76	     */
77	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
78	
79	    /**
80	     * Remembers, per {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key}, the id of the owner that key's
81	     * first successful create produced, so a repeat of that create can return the same owner rather
82	     * than creating a duplicate.
83	     */
84	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
85	
86	    /**
87	     * Fixed public-holiday calendar. A registration date that lands on one of these dates is rolled
88	     * forward to the next non-holiday business day, in the same way weekends are.
89	     */
90	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
91	        LocalDate.of(2026, 1, 1),
92	        LocalDate.of(2026, 1, 26),
93	        LocalDate.of(2026, 4, 25),
94	        LocalDate.of(2026, 12, 25),
95	        LocalDate.of(2026, 12, 28));
96	
97	    private final ClinicService clinicService;
98	
99	    private final OwnerMapper ownerMapper;
100	
101	    private final PetMapper petMapper;
102	
103	    private final VisitMapper visitMapper;
104	
105	    private final AddressNormalizer addressNormalizer;
106	
107	    public OwnerRestControllerV1(ClinicService clinicService,
108	                                 OwnerMapper ownerMapper,
109	                                 PetMapper petMapper,
110	                                 VisitMapper visitMapper,
111	                                 AddressNormalizer addressNormalizer) {
112	        this.clinicService = clinicService;
113	        this.ownerMapper = ownerMapper;
114	        this.petMapper = petMapper;
115	        this.visitMapper = visitMapper;
116	        this.addressNormalizer = addressNormalizer;
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
122	        Collection<Owner> owners;
123	        if (lastName != null) {
124	            owners = this.clinicService.findOwnerByLastName(lastName);
125	        } else {
126	            owners = this.clinicService.findAllOwners();
127	        }
128	        if (owners.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
147	        String idempotencyKey = currentIdempotencyKey();
148	        if (idempotencyKey != null) {
149	            Integer existingId = idempotentCreates.get(idempotencyKey);
150	            if (existingId != null) {
151	                Owner existing = this.clinicService.findOwnerById(existingId);
152	                if (existing != null) {
153	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
154	                }
155	            }
156	        }
157	
158	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
159	
160	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
161	            && response.getBody() != null && response.getBody().getId() != null) {
162	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
163	        }
164	        return response;
165	    }
166	
167	    /**
168	     * The non-blank {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key} header of the request currently
169	     * being handled, or {@code null} when the request carries no such header (or no request is bound
170	     * to the current thread). Used to make a repeated create return the originally created owner.
171	     */
172	    private String currentIdempotencyKey() {
173	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
174	            return null;
175	        }
176	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
177	        return (key == null || key.isBlank()) ? null : key;
178	    }
179	
180	    /**
181	     * Run the full owner-creation pipeline for a submitted {@link OwnerFieldsDto} and build its
182	     * response. The submitted fields are mapped to an {@link Owner}, which is
183	     * {@link #normalizeAndValidate(Owner) normalized and validated}, checked against the
184	     * {@link #isDailyLimitReached(LocalDate) daily creation limit}, {@link #assignHousehold(Owner)
185	     * assigned its household} and screened for {@link #checkForConflicts(Owner, boolean) conflicts};
186	     * a surviving owner then has its {@link #assignDerivedAttributes(Owner, boolean) derived
187	     * attributes} assigned, is persisted and audited. Returns the {@link #created(Owner) 201 Created}
188	     * response for the persisted owner, or the {@link HttpStatus} the create must fail with
189	     * ({@code 400 Bad Request}, {@code 429 Too Many Requests} or {@code 409 Conflict}) when the owner
190	     * cannot be created.
191	     */
192	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
193	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
194	
195	        HttpStatus invalid = normalizeAndValidate(owner);
196	        if (invalid != null) {
197	            return new ResponseEntity<>(invalid);
198	        }
199	        if (isDailyLimitReached(owner.getRegistrationDate())) {
200	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
201	        }
202	
203	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
204	        assignHousehold(owner);
205	
206	        HttpStatus conflict = checkForConflicts(owner, sharesHousehold);
207	        if (conflict != null) {
208	            return new ResponseEntity<>(conflict);
209	        }
210	
211	        assignDerivedAttributes(owner, sharesHousehold);
212	        this.clinicService.saveOwner(owner);
213	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
214	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
215	            owner.getMembershipLevel(), owner.getMembershipNumber());
216	        return created(owner);
217	    }
218	
219	    /**
220	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
221	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
222	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
223	     * postcode is checked against its city's region, a registration date in the future is rejected,
224	     * and the effective registration date (the supplied one, or today when none was given) is rolled
225	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
226	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
227	     * otherwise.
228	     */
229	    private HttpStatus normalizeAndValidate(Owner owner) {
230	        if (!normalizeAddress(owner)) {
231	            return HttpStatus.BAD_REQUEST;
232	        }
233	        String telephone = toE164(owner.getTelephone());
234	        if (telephone == null) {
235	            return HttpStatus.BAD_REQUEST;
236	        }
237	        owner.setTelephone(telephone);
238	        if (isDisposableEmail(owner.getEmail())) {
239	            return HttpStatus.BAD_REQUEST;
240	        }
241	        if (!owner.isPostcodeValid()) {
242	            return HttpStatus.BAD_REQUEST;
243	        }
244	        if (owner.getRegistrationDate() != null
245	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
246	            return HttpStatus.BAD_REQUEST;
247	        }
248	        LocalDate effectiveDate = owner.getRegistrationDate() != null
249	            ? owner.getRegistrationDate() : LocalDate.now();
250	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
251	        return null;
252	    }
253	
254	    /**
255	     * Normalize the owner's supplied address into its canonical stored form and report whether an
256	     * address was supplied at all. The owner may supply its address either as the structured
257	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
258	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
259	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
260	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
261	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
262	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
263	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
264	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
265	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
266	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
267	     * create must be rejected with {@code 400 Bad Request}.
268	     */
269	    private boolean normalizeAddress(Owner owner) {
270	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
271	        if (!line1.isEmpty()) {
272	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
273	            owner.setAddressLine1(line1);
274	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
275	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
276	            return true;
277	        }
278	        String address = addressNormalizer.normalize(owner.getAddress());
279	        if (address.isEmpty()) {
280	            return false;
281	        }
282	        owner.setAddressLine1(null);
283	        owner.setAddressLine2(null);
284	        owner.setAddress(address);
285	        return true;
286	    }
287	
288	    /**
289	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
290	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
291	     */
292	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
293	        "mailinator.com", "tempmail.com", "guerrillamail.com");
294	
295	    /**
296	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
297	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
298	     * the domain (the part after the last {@code '@'}, compared case-insensitively) is matched
299	     * against the blocklist.
300	     */
301	    private boolean isDisposableEmail(String email) {
302	        if (email == null || email.isEmpty()) {
303	            return false;
304	        }
305	        int at = email.lastIndexOf('@');
306	        if (at < 0) {
307	            return false;
308	        }
309	        String domain = email.substring(at + 1).toLowerCase();
310	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
311	    }
312	
313	    /**
314	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
315	     * deterministically from the owner's lastName and postcode, so every owner sharing that
316	     * lastName and postcode is assigned the same value automatically, independent of whether the
317	     * owner declares it shares a household. The link is assigned before the
318	     * {@link #checkForConflicts(Owner, boolean) conflict checks} because it is part of the owner's
319	     * {@link Owner#getIdentityKey() identity} and feeds its {@link #householdSize(String) household
320	     * size}.
321	     */
322	    private void assignHousehold(Owner owner) {
323	        owner.setHouseholdId(householdId(owner));
324	    }
325	
326	    /**
327	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
328	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
329	     * {@link #isHouseholdDuplicate(Owner) duplicates an existing household} or when its
330	     * {@link #isCityAtCapacity(String) city is already at capacity}. Declaring {@code
331	     * sharesHousehold} bypasses only the household-duplicate block (the owner is then created as a
332	     * declared household member); it does not lift the city-capacity limit. Returns {@code null}
333	     * when the owner clashes with nothing and may be created.
334	     */
335	    private HttpStatus checkForConflicts(Owner owner, boolean sharesHousehold) {
336	        if (!sharesHousehold && isHouseholdDuplicate(owner)) {
337	            return HttpStatus.CONFLICT;
338	        }
339	        if (isCityAtCapacity(owner.getCity())) {
340	            return HttpStatus.CONFLICT;
341	        }
342	        return null;
343	    }
344	
345	    /**
346	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
347	     * {@code Location} header pointing at {@code /api/owners/{id}}.
348	     */
349	    private ResponseEntity<OwnerDto> created(Owner owner) {
350	        HttpHeaders headers = new HttpHeaders();
351	        headers.setLocation(UriComponentsBuilder.newInstance()
352	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
353	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
354	    }
355	
356	    /**
357	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
358	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
359	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
360	     * householdSize}. Each is computed from the owner's own fields together with the owners already
361	     * present, so this runs after the owner has been validated and has passed the duplicate and
362	     * capacity checks, and immediately before it is persisted.
363	     */
364	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
365	        owner.setCustomerCode(customerCode(owner));
366	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
367	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
368	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
369	        assignPossibleDuplicate(owner, sharesHousehold);
370	    }
371	
372	    /**
373	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
374	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
375	     * so it is never flagged. Otherwise, because this runs after the hard
376	     * {@link #isHouseholdDuplicate(Owner) household-duplicate} check, the owner is not a household
377	     * match; it is flagged only when it is a soft match of an existing owner as determined by
378	     * {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
379	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
380	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
381	     */
382	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
383	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
384	        owner.setPossibleDuplicate(match != null);
385	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
386	    }
387	
388	    /**
389	     * The owners a newly created owner is checked against by the duplicate and identity rules:
390	     * the {@link #isHouseholdDuplicate(Owner) household-duplicate} and {@link #findSoftDuplicate(Owner)
391	     * soft-duplicate} checks, the {@link #customerCode(Owner) customerCode} de-duplication and the
392	     * {@link #namesakeCount(String, String) namesake} count. This is the single place that scope is
393	     * defined, so every one of those rules considers exactly the same set of owners; it spans every
394	     * owner the clinic holds except those flagged {@linkplain Owner#isDeleted() deleted}, which a
395	     * soft delete retains but excludes from duplicate and identity detection.
396	     */
397	    private Collection<Owner> activeOwners() {
398	        return this.clinicService.findAllOwners().stream()
399	            .filter(owner -> !owner.isDeleted())
400	            .collect(Collectors.toList());
401	    }
402	
403	    /**
404	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
405	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
406	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
407	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
408	     * postcode never matches.
409	     */
410	    private Owner findSoftDuplicate(Owner owner) {
411	        if (owner.getPostcode() == null) {
412	            return null;
413	        }
414	        String candidateLastName = normalizeName(owner.getLastName());
415	        return activeOwners().stream()
416	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
417	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
418	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
419	            .min(Comparator.comparingInt(Owner::getId))
420	            .orElse(null);
421	    }
422	
423	    /**
424	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
425	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
426	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
427	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
428	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
429	     * every value built from the customer code (the membership number and its check digit) and the
430	     * owner's locality are derived from it.
431	     *
432	     * <p>When the computed code collides with an existing owner's {@code customerCode}, a
433	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the code
434	     * unique, and the de-duplicated code is returned.
435	     */
436	    private String customerCode(Owner owner) {
437	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
438	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
439	        String base = region + "-" + hash8;
440	
441	        Set<String> existingCodes = activeOwners().stream()
442	            .map(Owner::getCustomerCode)
443	            .filter(Objects::nonNull)
444	            .collect(Collectors.toSet());
445	
446	        if (!existingCodes.contains(base)) {
447	            return base;
448	        }
449	        int n = 2;
450	        while (existingCodes.contains(base + "-" + n)) {
451	            n++;
452	        }
453	        return base + "-" + n;
454	    }
455	
456	    /**
457	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
458	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
459	     * (business-day) registration date of the owner being created, so owners are counted per
460	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
461	     */
462	    private boolean isDailyLimitReached(LocalDate day) {
463	        long count = this.clinicService.findAllOwners().stream()
464	            .filter(existing -> day.equals(existing.getRegistrationDate()))
465	            .count();
466	        return count >= 100;
467	    }
468	
469	    /**
470	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
471	     * more than 80 owners have already been created for the given business day. Counts the owners
472	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
473	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
474	     * warning.
475	     */
476	    private boolean isBulkSignup(LocalDate day) {
477	        long count = this.clinicService.findAllOwners().stream()
478	            .filter(existing -> day.equals(existing.getRegistrationDate()))
479	            .count();
480	        return count > 80;
481	    }
482	
483	    /**
484	     * Roll a registration date forward onto a business day: when it falls on a Saturday, Sunday or a
485	     * listed public holiday, advance it to the next non-holiday weekday; an ordinary weekday is
486	     * returned unchanged.
487	     */
488	    private LocalDate toBusinessDay(LocalDate date) {
489	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
490	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
491	            || PUBLIC_HOLIDAYS.contains(date)) {
492	            date = date.plusDays(1);
493	        }
494	        return date;
495	    }
496	
497	    /**
498	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
499	     * more owners. Cities are compared case-insensitively.
500	     */
501	    private boolean isCityAtCapacity(String city) {
502	        long count = this.clinicService.findAllOwners().stream()
503	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
504	            .count();
505	        return count >= 50;
506	    }
507	
508	    /**
509	     * The number of existing owners that already share the given firstName and lastName,
510	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
511	     * whitespace runs collapsed). Counted over the owners present before this create.
512	     */
513	    private int namesakeCount(String firstName, String lastName) {
514	        String candidateFirstName = normalizeName(firstName);
515	        String candidateLastName = normalizeName(lastName);
516	        return (int) activeOwners().stream()
517	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
518	                && normalizeName(existing.getLastName()).equals(candidateLastName))
519	            .count();
520	    }
521	
522	    /**
523	     * The number of members in this owner's household after this create: the count of existing
524	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
525	     * created. An owner with no household ({@code householdId == null}) is a household of one.
526	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
527	     * does not depend on the order in which household members were created.
528	     */
529	    private int householdSize(String householdId) {
530	        if (householdId == null) {
531	            return 1;
532	        }
533	        long existing = this.clinicService.findAllOwners().stream()
534	            .filter(other -> householdId.equals(other.getHouseholdId()))
535	            .count();
536	        return (int) existing + 1;
537	    }
538	
539	    /**
540	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
541	     * cannot form a valid E.164 number.
542	     *
543	     * <p>A leading '+' and country code are kept when present; otherwise country code
544	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
545	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
546	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
547	     * exactly the national-digit count that code requires (see
548	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
549	     */
550	    private String toE164(String telephone) {
551	        if (telephone == null) {
552	            return null;
553	        }
554	        boolean hasCountryCode = telephone.trim().startsWith("+");
555	        String digits = telephone.replaceAll("\\D", "");
556	        String e164;
557	        if (hasCountryCode) {
558	            e164 = digits;
559	        } else {
560	            if (digits.startsWith("0")) {
561	                digits = digits.substring(1);
562	            }
563	            e164 = "61" + digits;
564	        }
565	        if (e164.length() < 8 || e164.length() > 15) {
566	            return null;
567	        }
568	        if (!Owner.hasValidNationalLength(e164)) {
569	            return null;
570	        }
571	        return "+" + e164;
572	    }
573	
574	    /**
575	     * Whether the candidate owner belongs to a household that already exists, and so must be
576	     * rejected with {@code 409 Conflict} unless it declares {@code sharesHousehold}. The household
577	     * is keyed by the deterministic {@link #householdId(Owner) householdId} (derived from lastName
578	     * and postcode), so any existing owner carrying the same householdId means this owner is a
579	     * second member of an already-registered household. Two owners sharing a lastName and postcode
580	     * are therefore the same household: the second is a household duplicate.
581	     */
582	    private boolean isHouseholdDuplicate(Owner owner) {
583	        String householdId = owner.getHouseholdId();
584	        if (householdId == null) {
585	            return false;
586	        }
587	        return activeOwners().stream()
588	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
589	    }
590	
591	    /**
592	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
593	     * to a single space and lower-case. A null value normalizes to the empty string.
594	     */
595	    private String normalizeName(String value) {
596	        if (value == null) {
597	            return "";
598	        }
599	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
600	    }
601	
602	    /**
603	     * A stable shared identifier for the household an owner belongs to, derived deterministically
604	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
605	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
606	     * assigned the same value regardless of the order in which they are created. Formatted as the
607	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
608	     * (an absent postcode contributes the empty string).
609	     */
610	    private String householdId(Owner owner) {
611	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
612	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
613	        return shaHexUpper(key).substring(0, 12);
614	    }
615	
616	    /**
617	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
618	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
619	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
620	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
621	     * {@link #customerCode} keeps the first 8).
622	     */
623	    private String shaHexUpper(String input) {
624	        try {
625	            byte[] digest = MessageDigest.getInstance("SHA-256")
626	                .digest(input.getBytes(StandardCharsets.UTF_8));
627	            StringBuilder sb = new StringBuilder(digest.length * 2);
628	            for (byte b : digest) {
629	                sb.append(String.format("%02x", b));
630	            }
631	            return sb.toString().toUpperCase();
632	        }
633	        catch (NoSuchAlgorithmException e) {
634	            throw new IllegalStateException("SHA-256 not available", e);
635	        }
636	    }
637	
638	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
639	    @Override
640	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
641	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
642	        if (currentOwner == null) {
643	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
644	        }
645	        currentOwner.setAddress(ownerFieldsDto.getAddress());
646	        currentOwner.setCity(ownerFieldsDto.getCity());
647	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
648	        currentOwner.setLastName(ownerFieldsDto.getLastName());
649	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
650	        this.clinicService.saveOwner(currentOwner);
651	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
652	    }
653	
654	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
655	    @Transactional
656	    @Override
657	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
658	        Owner owner = this.clinicService.findOwnerById(ownerId);
659	        if (owner == null) {
660	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
661	        }
662	        this.clinicService.deleteOwner(owner);
663	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
664	    }
665	
666	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
667	    @Override
668	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
669	        Owner owner = this.clinicService.findOwnerById(ownerId);
670	        if (owner == null) {
671	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
672	        }
673	        HttpHeaders headers = new HttpHeaders();
674	        Pet pet = petMapper.toPet(petFieldsDto);
675	        owner.setId(ownerId);
676	        pet.setOwner(owner);
677	        pet.getType().setName(null);
678	        this.clinicService.savePet(pet);
679	        PetDto petDto = petMapper.toPetDto(pet);
680	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
681	            .buildAndExpand(pet.getId()).toUri());
682	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
683	    }
684	
685	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
686	    @Override
687	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
688	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
689	        if (currentOwner != null) {
690	            Pet currentPet = this.clinicService.findPetById(petId);
691	            if (currentPet != null) {
692	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
693	                currentPet.setName(petFieldsDto.getName());
694	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
695	                this.clinicService.savePet(currentPet);
696	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
697	            }
698	        }
699	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
700	    }
701	
702	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
703	    @Override
704	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
705	        HttpHeaders headers = new HttpHeaders();
706	        Visit visit = visitMapper.toVisit(visitFieldsDto);
707	        Pet pet = new Pet();
708	        pet.setId(petId);
709	        visit.setPet(pet);
710	        this.clinicService.saveVisit(visit);
711	        VisitDto visitDto = visitMapper.toVisitDto(visit);
712	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
713	            .buildAndExpand(visit.getId()).toUri());
714	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
715	    }
716	
717	
718	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
719	    @Override
720	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
721	        Owner owner = this.clinicService.findOwnerById(ownerId);
722	        if (owner != null) {
723	            Pet pet = owner.getPet(petId);
724	            if (pet != null) {
725	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
726	            }
727	        }
728	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
729	    }
730	}
