308	    /**
309	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
310	     * last two digits of the {@linkplain #getFiscalYear() fiscal year} of the
311	     * (business-day-adjusted) registrationDate, e.g. {@code 'NSW-3C1A9F2B-M27'}.
312	     */
313	    public String getMembershipNumber() {
314	        return this.customerCode + "-M" + String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
315	    }
