317	    /**
318	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the last two digits of the
319	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the (business-day-adjusted)
320	     * {@link #registrationDate}, e.g. {@code 'FY27'}. The fiscal year starts on 1 July and is
321	     * labelled by the calendar year in which it ends.
322	     */
323	    public String getFiscalYear() {
324	        return "FY" + String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
325	    }
326	
327	    /**
328	     * The fiscal year that contains the given date, identified by the calendar year in which it
329	     * ends. The fiscal year starts on 1 July, so a date in July through December belongs to the
330	     * fiscal year ending in the following calendar year, while a date in January through June
331	     * belongs to the fiscal year ending in the same calendar year.
332	     */
333	    private static int fiscalYearOf(LocalDate date) {
334	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
335	    }
336	
337	    /**
338	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
339	     * contained in the owner's {@link #customerCode}.
340	     */
341	    public int getCheckDigit() {
342	        return luhnCheckDigit(this.customerCode);
343	    }
344	
345	    /**
346	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
347	     * contained in {@code value}. Reading the digits right to left, every second one is
348	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
349	     * digits are summed, and the check digit is the amount that must be added to that sum to
350	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
351	     * the digit is taken over exactly the digits the string carries.
352	     */
353	    private static int luhnCheckDigit(String value) {
354	        int sum = 0;
355	        boolean doubling = true;
356	        for (int i = value.length() - 1; i >= 0; i--) {
357	            char c = value.charAt(i);
358	            if (c < '0' || c > '9') {
359	                continue;
360	            }
361	            int digit = c - '0';
362	            if (doubling) {
363	                digit *= 2;
364	                if (digit > 9) {
365	                    digit -= 9;
366	                }
367	            }
368	            sum += digit;
369	            doubling = !doubling;
370	        }
371	        return (10 - (sum % 10)) % 10;
372	    }
373	
374	    /** Fixed city-to-region table used to derive an owner's locality. */
375	    private static final Map<String, String> CITY_REGION = Map.of(
376	        "Sydney", "NSW",
377	        "Melbourne", "VIC",
378	        "Brisbane", "QLD");
379	
380	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
381	    public static final String UNKNOWN_REGION = "UNKNOWN";
382	
383	    /**
384	     * The canonical region for a city, derived from the fixed city-to-region table
385	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
386	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
387	     * source of the city-to-region mapping, shared by every rule that is keyed by
388	     * region so the mapping is never re-derived elsewhere.
389	     */
390	    public static String regionOf(String city) {
391	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
392	    }
393	
394	    /**
395	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
396	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
397	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
398	     * known region). Locality is read from the region-and-hash identity so it never re-derives
399	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
400	     */
401	    public String getLocality() {
402	        if (this.customerCode == null) {
403	            return UNKNOWN_REGION;
404	        }
405	        int dash = this.customerCode.indexOf('-');
406	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
407	    }
408	
409	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
410	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
411	        "NSW", "Australia/Sydney",
412	        "VIC", "Australia/Melbourne",
413	        "QLD", "Australia/Brisbane");
414	
415	    /**
416	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
417	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
418	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
419	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
420	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
421	     */
422	    public String getTimezone() {
423	        return REGION_TIMEZONE.get(getLocality());
424	    }
425	
426	    /**
427	     * The region derived from this owner's postcode alone: the region whose fixed
428	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
429	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
430	     * component built into the owner's customer code at creation and, through it, the source of the
431	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
432	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
433	     */
434	    public String getRegion() {
435	        return regionOfPostcode(this.postcode);
436	    }
437	
438	    /**
439	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
440	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
441	     * no known range.
442	     */
443	    private static String regionOfPostcode(String postcode) {
444	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
445	            return null;
446	        }
447	        int value = Integer.parseInt(postcode);
448	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
449	            int[] range = entry.getValue();
450	            if (value >= range[0] && value <= range[1]) {
451	                return entry.getKey();
452	            }
453	        }
454	        return null;
455	    }
456	
457	    /**
458	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
459	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
460	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
461	     */
462	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
463	        "NSW", new int[] {2000, 2099},
464	        "VIC", new int[] {3000, 3099},
465	        "QLD", new int[] {4000, 4099});
466	
467	    /**
468	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
469	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
470	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
471	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
472	     * city with no known region accepts any 4-digit postcode.
473	     */
474	    public boolean isPostcodeValid() {
475	        if (this.postcode == null) {
476	            return true;
477	        }
478	        if (!this.postcode.matches("[0-9]{4}")) {
479	            return false;
480	        }
481	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
482	        if (range == null) {
483	            return true;
484	        }
485	        int value = Integer.parseInt(this.postcode);
486	        return value >= range[0] && value <= range[1];
487	    }
488	
489	    /**
490	     * The national (subscriber) digit count required by each known country calling code, keyed by
491	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
492	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
493	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
494	     * re-derived elsewhere.
495	     */
496	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
497	        "1", 10,
498	        "61", 9);
499	
500	    /**
501	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
502	     * E.164 digit string, choosing the longest matching code known to
503	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
504	     * country code. This is the single place a country code is read from an E.164 number, so every
505	     * rule keyed by that code shares one derivation.
506	     */
507	    private static String countryCodeOf(String e164Digits) {
508	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
509	            .filter(e164Digits::startsWith)
510	            .max(Comparator.comparingInt(String::length))
511	            .orElse(null);
512	    }
513	
514	    /**
515	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
516	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
517	     * known code wins; a number whose country code is not recognised passes this check (its length is
518	     * then governed only by the general E.164 bound), while a recognised code must be followed by
519	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
520	     */
521	    public static boolean hasValidNationalLength(String e164Digits) {
522	        String countryCode = countryCodeOf(e164Digits);
523	        if (countryCode == null) {
524	            return true;
525	        }
526	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
527	    }
528	
529	    /**
530	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
531	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
532	     * gain 3 when the owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one
533	     * elapsed fiscal year. The email, namesake and household factors are available on creation; the
534	     * tenure factor is reached only once at least one fiscal-year boundary has passed.
535	     */
536	    public Integer getMembershipPoints() {
537	        int points = 0;
538	        if (hasEmail()) {
539	            points += 2;
540	        }
541	        if (hasNoNamesakes()) {
542	            points += 1;
543	        }
544	        if (hasLargeHousehold()) {
545	            points += 2;
546	        }
547	        if (hasQualifyingTenure()) {
548	            points += 3;
549	        }
550	        return points;
551	    }
552	
553	    /**
554	     * The owner's membership level, a number from 1 to 4 derived from {@linkplain #getMembershipPoints()
555	     * membershipPoints}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or
556	     * more.
557	     */
558	    public Integer getMembershipLevel() {
559	        int points = getMembershipPoints();
560	        if (points >= 6) {
561	            return 4;
562	        }
563	        if (points >= 4) {
564	            return 3;
565	        }
566	        if (points >= 2) {
567	            return 2;
568	        }
569	        return 1;
570	    }
571	
572	    /**
573	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
574	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
575	     * known, is treated as not a large household.
576	     */
577	    private boolean hasLargeHousehold() {
578	        return this.householdSize != null && this.householdSize >= 3;
579	    }
580	
581	    /**
582	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
583	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
584	     * email presence so the check is never re-derived elsewhere.
585	     */
586	    private boolean hasEmail() {
587	        return this.email != null && !this.email.isEmpty();
588	    }
589	
590	    /**
591	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
592	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
593	     * not known, is treated as not unique.
594	     */
595	    private boolean hasNoNamesakes() {
596	        return this.namesakeCount != null && this.namesakeCount == 0;
597	    }
598	
599	    /**
600	     * Whether this owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one elapsed
601	     * fiscal year. A newly created owner (zero elapsed fiscal years) does not qualify; the threshold
602	     * is crossed only once at least one fiscal-year boundary has passed since registration.
603	     */
604	    private boolean hasQualifyingTenure() {
605	        return this.getTenureFiscalYears() >= 1;
606	    }
607	
608	    /**
609	     * The owner's tenure in elapsed fiscal years: the number of fiscal-year boundaries between the
610	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the {@link #registrationDate} and the
611	     * fiscal year of the current date, or {@code 0} when the registrationDate is not yet set (a newly
612	     * created owner has zero tenure). Never negative.
613	     */
614	    public long getTenureFiscalYears() {
615	        if (this.registrationDate == null) {
616	            return 0;
617	        }
618	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
619	    }
620	
621	    /**
622	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
623	     * otherwise {@code 'PHONE'}.
624	     */
625	    public String getContactPreference() {
626	        return hasEmail() ? "EMAIL" : "PHONE";
627	    }
628	
629	    /**
630	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
631	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
632	     * the national digits grouped into threes from the left separated by spaces,
633	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
634	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
635	     * E.164 form, or carries no known country code.
636	     */
637	    public String getTelephoneDisplay() {
638	        if (this.telephone == null || !this.telephone.startsWith("+")) {
639	            return this.telephone;
640	        }
641	        String digits = this.telephone.substring(1);
642	        String countryCode = countryCodeOf(digits);
643	        if (countryCode == null) {
644	            return this.telephone;
645	        }
646	        String national = digits.substring(countryCode.length());
647	        StringBuilder groups = new StringBuilder();
648	        for (int i = 0; i < national.length(); i += 3) {
649	            if (groups.length() > 0) {
650	                groups.append(' ');
651	            }
652	            groups.append(national, i, Math.min(i + 3, national.length()));
653	        }
654	        return "+" + countryCode + " " + groups;
655	    }
656	
657	    /**
658	     * The owner's identity key: the single derived value used for duplicate detection.
659	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
660	     * empty string when absent) and the householdId (or the empty string when the owner
661	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
662	     * Two owners are duplicates only when their whole identity keys are equal.
663	     */
664	    public String getIdentityKey() {
665	        String telephonePart = this.telephone == null ? "" : this.telephone;
666	        String emailPart = this.email == null ? "" : this.email;
667	        String householdPart = this.householdId == null ? "" : this.householdId;
668	        return telephonePart + "|" + emailPart + "|" + householdPart;
669	    }
670	
671	    protected Set<Pet> getPetsInternal() {
672	        if (this.pets == null) {
673	            this.pets = new HashSet<>();
674	        }
675	        return this.pets;
676	    }
677	
678	    protected void setPetsInternal(Set<Pet> pets) {
679	        this.pets = pets;
680	    }
681	
682	    public List<Pet> getPets() {
683	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
684	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
685	        return Collections.unmodifiableList(sortedPets);
686	    }
687	
688	    public void setPets(List<Pet> pets) {
689	        this.pets = new HashSet<>(pets);
690	    }
691	
692	    public void addPet(Pet pet) {
693	        getPetsInternal().add(pet);
694	        pet.setOwner(this);
695	    }
696	
697	    /**
698	     * Return the Pet with the given name, or null if none found for this Owner.
699	     *
700	     * @param name to test
701	     * @return true if pet name is already in use
702	     */
703	    public Pet getPet(String name) {
704	        return getPet(name, false);
705	    }
706	
707	    /**
708	     * Return the Pet with the given name, or null if none found for this Owner.
709	     *
710	     * @param name to test
711	     * @return true if pet name is already in use
712	     */
713	    public Pet getPet(String name, boolean ignoreNew) {
714	        name = name.toLowerCase();
715	        for (Pet pet : getPetsInternal()) {
716	            if (!ignoreNew || !pet.isNew()) {
717	                String compName = pet.getName();
718	                compName = compName.toLowerCase();
719	                if (compName.equals(name)) {
720	                    return pet;
721	                }
722	            }
723	        }
724	        return null;
725	    }
726	
727	    public Pet getPet(Integer petId) {
728	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
729	    }
730	
731	    @Override
732	    public String toString() {
733	        return new ToStringCreator(this)
734	
735	            .append("id", this.getId())
736	            .append("new", this.isNew())
737	            .append("lastName", this.getLastName())
738	            .append("firstName", this.getFirstName())
739	            .append("address", this.address)
740	            .append("city", this.city)
741	            .append("telephone", this.telephone)
742	            .append("email", this.email)
743	            .toString();
744	    }
745	}
